<?php
require_once __DIR__ . '/_auth.php';
require_once dirname(__DIR__) . '/lib/property-store.php';
$owner=owner_require_login();
header('Cache-Control: no-store');
$ref=trim((string)($_REQUEST['reference_id']??''));
$r=li_load_property($ref);
if(!$r){http_response_code(404);exit('Property not found');}
$ownerId=(string)($r['owner']['account_id']??'');
$mine=($ownerId!=='' && hash_equals($ownerId,(string)($owner['id']??''))) || ($ownerId==='' && normalize_mobile((string)($r['owner']['mobile']??''))===normalize_mobile((string)($owner['mobile']??'')));
if(!$mine || ($r['status']??'')==='OWNER_DELETED'){http_response_code(403);exit('Not allowed');}
$error='';
$p=$r['property']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!owner_csrf_valid($_POST['csrf']??null)){http_response_code(403);exit('Invalid CSRF token');}
 $clean=function($k,$max=255){$v=trim((string)($_POST[$k]??''));return mb_substr(preg_replace('/[\x00-\x1F\x7F]/u','',$v),0,$max);};
 $purpose=$clean('purpose',20); $type=$clean('type',80); $area=$clean('area',50); $price=$clean('price',20); $city=$clean('city',80); $locality=$clean('locality',120); $address=$clean('address',500); $description=$clean('description',1500);
 if(!in_array($purpose,['Sale','Rent'],true)||$type===''||$area===''||$price===''||$city===''||$locality===''||$address===''||$description===''){$error='Please complete all required fields.';} else {
   $from=(string)($r['status']??'PENDING_VERIFICATION');
   $r['property']['purpose']=$purpose; $r['property']['type']=$type; $r['property']['configuration']=$clean('configuration',50); $r['property']['area']=$area; $r['property']['price']=$price; $r['property']['project_name']=$clean('project_name',120); $r['property']['city']=$city; $r['property']['locality']=$locality; $r['property']['address']=$address; $r['property']['description']=$description;
   $r['property']['negotiable']=isset($_POST['negotiable']); $r['property']['ready_to_move']=isset($_POST['ready_to_move']); $r['property']['featured_request']=isset($_POST['featured_request']);
   $r['status']='PENDING_VERIFICATION'; $r['updated_at']=gmdate('c'); unset($r['published_at']);
   $r['verification']['verified']=false; $r['verification']['verified_at']=null; $r['verification']['verified_by']=null;
   li_audit($r,$from,'PENDING_VERIFICATION','OWNER_EDIT','Owner updated property details; sent for review.');
   if(li_save_property($r)){header('Location: /owner/dashboard.php?updated=1');exit;} $error='Could not save changes.';
 }
 $p=$r['property']??[];
}
function sel($a,$b){return (string)$a===(string)$b?' selected':'';}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Property | Leads India</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 text-white min-h-screen"><main class="max-w-3xl mx-auto px-4 py-8"><div class="flex justify-between items-center"><div><h1 class="text-2xl font-black">Edit Property</h1><p class="text-slate-400 text-sm"><?=htmlspecialchars($ref)?></p></div><a href="/owner/dashboard.php" class="px-4 py-2 bg-white/10 rounded-xl">Back</a></div><?php if($error):?><div class="mt-4 p-3 bg-red-500/10 border border-red-500/30 rounded-xl text-red-200"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" class="mt-6 grid md:grid-cols-2 gap-4"><input type="hidden" name="csrf" value="<?=htmlspecialchars(owner_csrf_token())?>"><input type="hidden" name="reference_id" value="<?=htmlspecialchars($ref)?>"><label>Purpose<select name="purpose" required class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"><option value="Sale"<?=sel($p['purpose']??'','Sale')?>>Sale</option><option value="Rent"<?=sel($p['purpose']??'','Rent')?>>Rent</option></select></label><label>Property Type<select name="type" required class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"><?php foreach(['Apartment','House/Villa','Plot/Land','Shop','Office','Commercial','Warehouse','Other'] as $v):?><option<?=sel($p['type']??'',$v)?>><?=htmlspecialchars($v)?></option><?php endforeach;?></select></label><label>Configuration<select name="configuration" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"><?php foreach(['','1 RK','1 BHK','2 BHK','3 BHK','4 BHK','5+ BHK','Studio','NA'] as $v):?><option value="<?=htmlspecialchars($v)?>"<?=sel($p['configuration']??'',$v)?>><?=htmlspecialchars($v===''?'Select':$v)?></option><?php endforeach;?></select></label><label>Area<input name="area" required value="<?=htmlspecialchars($p['area']??'')?>" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"></label><label>Price<input name="price" required value="<?=htmlspecialchars($p['price']??'')?>" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"></label><label>Project / Society<input name="project_name" value="<?=htmlspecialchars($p['project_name']??'')?>" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"></label><label>City<input name="city" required value="<?=htmlspecialchars($p['city']??'')?>" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"></label><label>Locality<input name="locality" required value="<?=htmlspecialchars($p['locality']??'')?>" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"></label><label class="md:col-span-2">Address<textarea name="address" required class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"><?=htmlspecialchars($p['address']??'')?></textarea></label><label class="md:col-span-2">Description<textarea name="description" required rows="5" class="mt-1 w-full p-3 rounded-xl bg-slate-900 border border-white/10"><?=htmlspecialchars($p['description']??'')?></textarea></label><div class="md:col-span-2 grid sm:grid-cols-3 gap-3"><?php foreach([['negotiable','Price Negotiable'],['ready_to_move','Ready to Move'],['featured_request','Request Featured'] ] as [$k,$t]):?><label class="flex items-center justify-between p-3 rounded-xl bg-slate-900 border border-white/10"><span><?=htmlspecialchars($t)?></span><input type="checkbox" name="<?=$k?>" class="w-5 h-5" <?=!empty($p[$k])?'checked':''?>></label><?php endforeach;?></div><div class="md:col-span-2 p-3 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-100 text-sm">Saving changes sends the property back to verification. If backend does not review it within 24 hours, auto-live policy applies.</div><button class="md:col-span-2 py-3 rounded-xl bg-emerald-600 font-black">Save Changes</button></form></main></body></html>